function checkLimits(f, text, steps) {
  const bytes = Buffer.byteLength(text, 'utf8');
  if (bytes > LIMITS.definitionBytes) f.error('limit', 'definition-size', `Definition is ${bytes} bytes; the limit is ${LIMITS.definitionBytes} bytes (50 KB).`);
  if (steps.length > LIMITS.totalSteps) f.error('limit', 'total-steps', `${steps.length} steps (including steps inside loops) exceeds the limit of ${LIMITS.totalSteps}.`, 'steps');
  const stateKeys = steps.filter(({ step }) => isMap(step) && step.type === 'state' && isMap(step.inputs)).reduce((n, { step }) => n + Object.keys(step.inputs).length, 0);
  if (stateKeys > LIMITS.stateKeysTotal) {
    f.warning('limit', 'state-keys-total', `${stateKeys} state keys are set across state steps; a run may store at most ${LIMITS.stateKeysTotal} (repeated keys overwrite, so this static count may overstate it).`, 'steps');
  }
}

export function checkSecretRef(segment) {
  const body = segment.trim();
  if (!SECRET_INTENT.test(body)) return null;
  const match = body.match(/^:secrets:(.+)$/);
  if (!match) return 'must use the form ${{ :secrets:NAME }}, ${{ :secrets:NAMESPACE:NAME }}, or ${{ :secrets:SCOPE:NAMESPACE:NAME }}';
  const parts = match[1].split(':');
  if (parts.length > 3) return 'has more than 3 segments after ":secrets:"';
  if (parts.some((p) => !SECRET_PART.test(p))) return 'has an empty or invalid segment (allowed: letters, digits, "_" and "-")';
  if (parts.length === 3 && !SECRET_SCOPES.includes(parts[0])) return `scope must be ${SECRET_SCOPES.join(' or ')} (got "${parts[0]}")`;
  return null;
}

